mapper.sql:
owner_key = #{ownerKey} and kind = #{kind}
and (

    content_hash = #{contentHash} or



        target_id = #{targetId}


        album_id = #{albumId} and seq = #{seq}


)

mapper.insert:
insert into media_recent (owner_key, kind, target_id, album_id, seq, content_hash, pos, dur, updated_at)
select #{toOwnerKey}, r.kind, r.target_id, r.album_id, r.seq, r.content_hash, r.pos, r.dur, r.updated_at
  from media_recent r
 where r.owner_key = #{fromOwnerKey}
   and not exists (
       select 1 from media_recent x
        where x.owner_key = #{toOwnerKey}
          and x.kind = r.kind
          and (
              (r.content_hash is not null and x.content_hash = r.content_hash)
           or (r.content_hash is null and (
                  (r.kind = 'video' and x.target_id = r.target_id)
               or (r.kind = 'photo' and x.album_id = r.album_id and x.seq = r.seq)
              ))
          )
   )
